      const outcome = await Promise.race([
        this.rpc("finishLink", params, token, generation).then(() => "finished" as const),
        new Promise<"refresh" | "cancel">(resolve => {
          timer = setTimeout(() => resolve("refresh"), 60000); timer.unref?.();
